def calculate_attribute_modifier(score):
    return (score - 10) // 2

def calculate_maximum_spell_level(score):
    if score < 1:
        return -1
    elif score <= 10:
        return 0
    elif score <= 12:
        return 1
    elif score <= 14:
        return 2
    elif score <= 16:
        return 3
    elif score <= 18:
        return 4
    else:
        return 9

