import re

def normalize(name):
    name = name.lower()
    name = re.sub(r'\s+', ' ', name)
    name = re.sub(r'[!;?:]', '', name)
    return name

def could_be(original, another):
    def normalize(name):
        name = name.lower()
        name = re.sub(r'\s+', ' ', name)
        name = re.sub(r'[!;?:]', '', name)
        return name

    def is_composed(name):
        return any(char in name for char in " -")

    def match_composed(original, another):
        original_parts = original.split()
        another_parts = another.split()
        return set(original_parts).issubset(set(another_parts)) and set(another_parts).issubset(set(original_parts))

    original = normalize(original)
    another = normalize(another)

    if is_composed(original) and is_composed(another):
        return match_composed(original, another)
    else:
        return original == another

